using System;
using System.Collections.Generic;
using System.IO;
using System.Linq;
using System.Reflection;
using System.Text;
using System.Threading.Tasks;
namespace ClassroomUpdater {
 internal static class AdvancedRecoveryChecks {
  internal static int Run(string output){Directory.CreateDirectory(output);string root=Path.Combine(output,"offline-copies");Directory.CreateDirectory(root);var rows=new List<object>();int failed=0;void Check(string name,Action action){try{action();rows.Add(new{name,passed=true});}catch(Exception e){failed++;rows.Add(new{name,passed=false,error=e.ToString()});}finally{Program.ApplyFault=null;}}
   string[] files={"拍照解题助教.exe","WpfMath.dll","Newtonsoft.Json.dll"};
   (string stage,string target) Pair(string name){string stage=Path.Combine(root,name,"stage"),target=Path.Combine(root,name,"target");Directory.CreateDirectory(stage);Directory.CreateDirectory(target);foreach(string f in files){File.WriteAllText(Path.Combine(stage,f),"new:"+f);File.WriteAllText(Path.Combine(target,f),"old:"+f);}File.WriteAllText(Path.Combine(target,"接口配置_仅自用.json"),"offline synthetic config sentinel");return(stage,target);}
   Check("Nth replace failure restores and verifies every file without touching config",()=>{var p=Pair("replace-failure");Program.ApplyFault=(phase,file)=>{if(phase=="replace"&&file==files[2])throw new IOException("injected replacement");};try{Program.Apply(p.stage,p.target,files.ToList());throw new Exception("expected failure");}catch(IOException e){if(!e.Message.Contains("逐项核验恢复"))throw;}foreach(string f in files)if(File.ReadAllText(Path.Combine(p.target,f))!="old:"+f)throw new Exception("mixed file "+f);if(!File.ReadAllText(Path.Combine(p.target,"接口配置_仅自用.json")).Contains("sentinel"))throw new Exception("configuration overwritten");if(!Directory.GetFiles(Path.Combine(p.target,"更新回退"),"preserve.failed",System.IO.SearchOption.AllDirectories).Any())throw new Exception("failed backup not marked");});
   Check("one rollback failure does not stop later rollback and never claims recovery",()=>{var p=Pair("rollback-failure");var rollback=new List<string>();Program.ApplyFault=(phase,file)=>{if(phase=="replace"&&file==files[2])throw new IOException("replacement failure");if(phase=="rollback"){rollback.Add(file);if(file==files[1])throw new IOException("rollback failure");}};try{Program.Apply(p.stage,p.target,files.ToList());throw new Exception("expected failure");}catch(IOException e){if(!e.Message.Contains("不要启动当前混合版本")||e.Message.Contains("已逐项核验恢复"))throw new Exception("false recovery claim");}if(!rollback.SequenceEqual(new[]{files[1],files[0]})||File.ReadAllText(Path.Combine(p.target,files[0]))!="old:"+files[0]||File.ReadAllText(Path.Combine(p.target,files[1]))!="new:"+files[1])throw new Exception("rollback did not continue in reverse");Program.TrimBackups(p.target);if(!Directory.GetFiles(Path.Combine(p.target,"更新回退"),"preserve.failed",SearchOption.AllDirectories).Any())throw new Exception("failed backup deleted");});
   Check("only two verified successful backups retained; failed and unknown backups preserved",()=>{var p=Pair("backup-retention");string failedDir=Path.Combine(p.target,"更新回退","20260101_000000_aaaaaaaa"),unknown=Path.Combine(p.target,"更新回退","20260101_000000_bbbbbbbb");Directory.CreateDirectory(failedDir);Directory.CreateDirectory(unknown);File.WriteAllText(Path.Combine(failedDir,"preserve.failed"),"keep");for(int i=0;i<4;i++)Program.Apply(p.stage,p.target,files.ToList());Program.TrimBackups(p.target);if(Directory.GetFiles(Path.Combine(p.target,"更新回退"),"verified.success",SearchOption.AllDirectories).Length!=2||!Directory.Exists(failedDir)||!Directory.Exists(unknown))throw new Exception("unsafe retention");});
   Check("failed stages survive cleanup while expired safe stages are removed",()=>{var p=Pair("stage-retention");string cache=Path.Combine(p.target,".update-cache"),failedStage=Path.Combine(cache,Guid.NewGuid().ToString("N")),old=Path.Combine(cache,Guid.NewGuid().ToString("N"));Directory.CreateDirectory(failedStage);Directory.CreateDirectory(old);File.WriteAllText(Path.Combine(failedStage,"preserve.failed"),"keep");Directory.SetLastWriteTimeUtc(failedStage,DateTime.UtcNow.AddDays(-7));Directory.SetLastWriteTimeUtc(old,DateTime.UtcNow.AddDays(-7));Program.CleanCache(p.target);if(!Directory.Exists(failedStage)||Directory.Exists(old))throw new Exception("failed stage lost");});
   Check("finished updater rejects a repeated install before any download or target writes",()=>{var p=Pair("repeat-install");using(var form=new UpdateForm("photo",p.target,"0.0.0","",false)){typeof(UpdateForm).GetField("finished",BindingFlags.Instance|BindingFlags.NonPublic).SetValue(form,true);typeof(UpdateForm).GetField("release",BindingFlags.Instance|BindingFlags.NonPublic).SetValue(form,new Dictionary<string,object>{{"version","9.0.0"}});((Task)typeof(UpdateForm).GetMethod("Install",BindingFlags.Instance|BindingFlags.NonPublic).Invoke(form,null)).GetAwaiter().GetResult();if(Directory.Exists(Path.Combine(p.target,".update-cache")))throw new Exception("repeat install started");}});
   Check("original PID must exit before replacement; new PID is alive before success",()=>{string exe=typeof(Program).Assembly.Location;using(var child=System.Diagnostics.Process.Start(new System.Diagnostics.ProcessStartInfo(exe,"--lifecycle-child"){UseShellExecute=false,CreateNoWindow=true})){ProcessLifecycle.WaitForOriginalExit(child.Id.ToString(),exe,3000).GetAwaiter().GetResult();if(!child.HasExited)throw new Exception("original remains active");}using(var child=ProcessLifecycle.StartAndCheck(exe,"--lifecycle-child").GetAwaiter().GetResult()){if(child.HasExited)throw new Exception("new PID missing");child.WaitForExit(3000);}});
   Check("mismatched PID is rejected without touching another process",()=>{string exe=typeof(Program).Assembly.Location;using(var child=System.Diagnostics.Process.Start(new System.Diagnostics.ProcessStartInfo(exe,"--lifecycle-child"){UseShellExecute=false,CreateNoWindow=true})){try{ProcessLifecycle.WaitForOriginalExit(child.Id.ToString(),Path.Combine(output,"not-the-program.exe"),10).GetAwaiter().GetResult();throw new Exception("wrong PID accepted");}catch(InvalidDataException){}if(child.HasExited)throw new Exception("unexpected close");child.WaitForExit(3000);}});
   Check("unwritable update-cache path reports failure and re-enables the button without network",()=>{var p=Pair("cache-path-denied");File.WriteAllText(Path.Combine(p.target,".update-cache"),"blocking fixture");using(var form=new UpdateForm("photo",p.target,"0.0.0","",false)){typeof(UpdateForm).GetField("release",BindingFlags.Instance|BindingFlags.NonPublic).SetValue(form,new Dictionary<string,object>{{"version","9.0.0"}});((Task)typeof(UpdateForm).GetMethod("Install",BindingFlags.Instance|BindingFlags.NonPublic).Invoke(form,null)).GetAwaiter().GetResult();var text=((System.Windows.Forms.Label)typeof(UpdateForm).GetField("status",BindingFlags.Instance|BindingFlags.NonPublic).GetValue(form)).Text;if(!text.Contains("目标目录不能创建更新缓存")||(bool)typeof(UpdateForm).GetField("working",BindingFlags.Instance|BindingFlags.NonPublic).GetValue(form))throw new Exception("permission failure left UI busy or lied about preserved stage");}});
   Check("Seewo stages stay pending until the running version confirms installation",()=>{var p=Pair("seewo-stage-confirmation");string cache=Path.Combine(p.target,".update-cache"),pending=Path.Combine(cache,Guid.NewGuid().ToString("N"));Directory.CreateDirectory(pending);File.WriteAllText(Path.Combine(pending,"installer.pending"),"not confirmed");File.WriteAllLines(Path.Combine(pending,"release.version"),new[]{"seewo","0.4.99"});Directory.SetLastWriteTimeUtc(pending,DateTime.UtcNow.AddDays(-5));Program.CleanCache(p.target,null,"seewo","0.4.15");if(!Directory.Exists(pending)||File.Exists(Path.Combine(pending,"verified.success")))throw new Exception("unconfirmed installer stage deleted");Program.CleanCache(p.target,null,"seewo","0.4.99");if(Directory.Exists(pending)&&!File.Exists(Path.Combine(pending,"verified.success")))throw new Exception("version confirmation not recorded");});
   File.WriteAllText(Path.Combine(output,"高级回退检查.json"),Program.Json.Serialize(new{failed,checks=rows,realInstallPerformed=false,productionProgramStarted=false}),Encoding.UTF8);return failed==0?0:1;
  }
 }
}
